  'elqb7vv91e': R`把 ⟦0⟧ 四舍五入到⟦1⟧。`,
  '10rdjn6n7af': R`看⟦0⟧右边一位上的数字，把 ⟦1⟧ 四舍五入为 <b>⟦2⟧</b>。`,
  'srl9a8gbof': R`哪个小数<b>最大</b>？&nbsp;⟦0⟧`,
  'gs5zz0z26m': R`哪个小数<b>最小</b>？&nbsp;⟦0⟧`,
  '1ddc7akhylh': R`都写成三位小数：⟦0⟧。最大的是 <b>⟦1⟧</b>。`,
  'clxur1r60o': R`都写成三位小数：⟦0⟧。最小的是 <b>⟦1⟧</b>。`,

  // percent
  'r0jl598zxh': R`
<p><b>百分数</b>表示“每 100 份中占几份”：$35\% = \frac{35}{100} = 0.35$。</p>
⟦0⟧
<h3>三类基本问题</h3>
⟦1⟧
⟦2⟧
<h3>增加、减少和折扣</h3>
<p>80 元的商品打八折（便宜 $20\%$），可以省 $0.2 \times 80 = 16$ 元，所以现价是 $80 - 16 = 64$ 元。更快的方法：只需付原价的 $80\%$，即 $0.8 \times 80 = 64$。</p>
<p>增加 $p\%$ 相当于乘 $1 + \frac{p}{100}$；减少 $p\%$ 相当于乘 $1 - \frac{p}{100}$。</p>
⟦3⟧`,
  '2e1ivkcc9wi': R`分数`,
  '21lfn42y4af': R`小数`,
  '1vaz29jk1go': R`百分数`,
  '1lj32zs95qv': R`<ul><li><b>求一个数的百分之几：</b> $N \text{ 的 } p\% = \frac{p}{100} \times N$。</li><li><b>$a$ 是 $b$ 的百分之几？</b> $\frac{a}{b} \times 100\%$。</li><li><b>变化率：</b> $\frac{\text{变化量}}{\text{原来的量}} \times 100\%$。</li></ul>`,
  '14zii6dfm6x': R`<p>$240$ 的 $15\%$ 是 $0.15 \times 240 = 36$。&nbsp; 口算技巧：$10\% = 24$，$5\% = 12$，合计 $36$。</p>`,
  '1xvrzy7qz2k': R`<p>求变化的百分率时，一定要除以<b>原来的</b>量。价格从 50 涨到 60，涨幅是 $\frac{10}{50} = 20\%$，而不是 $\frac{10}{60}$。</p>`,
  '1gobo82ltgo': R`⟦1⟧ 的 ⟦0⟧% 是多少？`,
  '17t3n1yumuv': R`$⟦1⟧ \text{ 的 } ⟦0⟧\% = \frac{⟦2⟧}{100} \times ⟦3⟧ = ⟦4⟧$。`,
  'x6d2i6pjon': R`⟦1⟧ 是 ⟦0⟧ 的百分之几？`,
  '166o0aldzl7': R`把 $\frac{⟦0⟧}{⟦1⟧}$ 化成百分数。`,
  '1zxz5pk8y96': R`一件夹克原价 ⟦0⟧ 元，现在降价 ⟦1⟧% 出售。现价是多少元？`,
  '1fg7th2fl2k': R`元`,
  '2d5e1injpmi': R`优惠金额 $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$。现价 $= ⟦3⟧ - ⟦4⟧ = ⟦5⟧$ 元。`,
  '188c7uiuhvg': R`某镇有 ⟦0⟧ 人，人口增长了 ⟦1⟧%。现在的人口是多少？`,
  '1z4269yh9sc': R`增加量 $= ⟦0⟧\% \times ⟦1⟧ = ⟦2⟧$。现在的人口 $= ⟦3⟧ + ⟦4⟧ = ⟦5⟧$。`,
  '24ppsoc883t': R`一本书的价格从 ⟦0⟧ 元变为 ⟦1⟧ 元。价格上涨了百分之几？`,
  '18zivp6w2kh': R`一本书的价格从 ⟦0⟧ 元变为 ⟦1⟧ 元。价格下降了百分之几？`,
  '275khxq1hou': R`变化量：⟦0⟧ 元。上涨的百分率：⟦1⟧——一定要除以<b>原来的</b>价格。`,
  '260avkxsjev': R`变化量：⟦0⟧ 元。下降的百分率：⟦1⟧——一定要除以<b>原来的</b>价格。`,

  // measurement
  'ymwylkippx': R`
<p>公制单位以 10 的乘方为基础，单位前的词头表示单位的大小。</p>
⟦0⟧
⟦1⟧
⟦2⟧
⟦3⟧
<h3>时间</h3>
<p>时间<i>不是</i>十进制的：1 小时是 60 分，而不是 100 分。求经过的时间时，可以分段往后数：从 09:35 到 13:10，先到 10:00 是 25 分，再到 13:00 是 3 小时，再加 10 分，共 3 小时 35 分 = 215 分钟。</p>
⟦4⟧`,
  '1vt4z8db5g': R`词头`,
  '18vrcwaxvwu': R`含义`,
  '1j1ms4p35q': R`例子`,
  '1837d2yv17g': R`千 (k)`,
  '6v2px6djsv': R`厘 (c)`,
  'cwnj8q0jlm': R`毫 (m)`,
  '4ynf6btmh8': R`量`,
  '1bcl39yblb4': R`换算`,
  '1yt0gqcalpk': R`长度`,
  '1pzczs2mse4': R`质量`,
  '3r7jg1gvau': R`1 t（吨）= 1,000 kg · 1 kg = 1,000 g`,
  '25cg9l2x1fi': R`容积`,
  '1ellrod4539': R`时间`,
  '149iz1sgt': R`1 min = 60 s · 1 h = 60 min · 1 天 = 24 h · 1 周 = 7 天`,
  '2g0x2qx5tup': R`<p>从<b>大</b>单位换成<b>小</b>单位，数量变多，要<b>乘</b>进率；从小单位换成大单位，要<b>除以</b>进率。</p>`,
  'x1upmnco35': R`<p>$3.5 \text{ km} = 3.5 \times 1000 = 3{,}500 \text{ m}$。&nbsp; $2{,}750 \text{ g} = 2{,}750 \div 1000 = 2.75 \text{ kg}$。</p>`,
  't9d9f384y5': R`<p>不要把时刻当成普通的数来相减：$13{:}10 - 9{:}35$ 不等于 $1310 - 935 = 375$ 分钟。</p>`,
  'q3mks7cmvp': R`把 ⟦0⟧ ⟦1⟧ 换算成 ⟦2⟧。`,
  '695i1r66ec': R`大单位换成小单位，所以乘：$⟦0⟧ \times ⟦1⟧ = ⟦2⟧$`,
  '1y3viru9jwt': R`小单位换成大单位，所以除：$⟦0⟧ \div ⟦1⟧ = ⟦2⟧$`,
  '10b6a48v5cr': R`⟦0⟧ 小时 ⟦1⟧ 分是多少分钟？`,
  '1jj8c6wfcmv': R`分钟`,
  '26onbfrmj2m': R`1 小时 = 60 分钟：$⟦0⟧ \times 60 + ⟦1⟧ = ⟦2⟧$ 分钟。`,
  '2fcfktfjfb2': R`⟦0⟧ 分 ⟦1⟧ 秒是多少秒？`,
  '1qje99e2i79': R`1 分钟 = 60 秒：$⟦0⟧ \times 60 + ⟦1⟧ = ⟦2⟧$ 秒。`,
  '1640fwpwscw': R`一列火车 ⟦0⟧ 出发，当天 ⟦1⟧ 到达。这段旅程用了多少分钟？`,
  '1bvdcgo9oas': R`从 ⟦0⟧ 到 ⟦1⟧ 经过了 ⟦2⟧ 小时 ⟦3⟧ 分，也就是 $⟦4⟧ \times 60 + ⟦5⟧ = ⟦6⟧$ 分钟。`,
  'jz7sp6v78m': R`计算 ⟦0⟧ m ⟦1⟧ cm 加 ⟦2⟧ m ⟦3⟧ cm，结果用厘米表示。`,
  '1v59jh3egmq': R`⟦0⟧ m ⟦1⟧ cm = ⟦2⟧ cm，⟦3⟧ m ⟦4⟧ cm = ⟦5⟧ cm。合计：$⟦6⟧ + ⟦7⟧ = ⟦8⟧$ cm。`,
