  'fbd3n0ai0s': R`一个三角形的两个角分别是 $⟦0⟧^\circ$ 和 $⟦1⟧^\circ$。第三个角是多少度？`,
  '1mgnf9acc40': R`三角形的内角和是 $180^\circ$：$180^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ = ⟦2⟧^\circ$。`,
  '17ra9ybal44': R`两个角在一条直线上组成平角，其中一个是 $⟦0⟧^\circ$。另一个是多少度？`,
