  'lbqlw4yngj': R`四个角围绕一点，其中三个分别是 $⟦0⟧^\circ$、$⟦1⟧^\circ$ 和 $⟦2⟧^\circ$。第四个角是多少度？`,
  '1q0g9lewnyf': R`围绕一点的角之和是 $360^\circ$：$360^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ - ⟦2⟧^\circ = ⟦3⟧^\circ$。`,
  '1o7rxocgbe4': R`$⟦0⟧^\circ$ 的角是什么角？`,
  '2087xqcuhit': R`锐角 $\lt 90^\circ$；直角 $= 90^\circ$；钝角在 $90^\circ$ 和 $180^\circ$ 之间；平角 $= 180^\circ$；优角在 $180^\circ$ 和 $360^\circ$ 之间。所以 $⟦0⟧^\circ$ 的角是<b>⟦1⟧</b>。`,
  '1em7emit9v': R`一个四边形有三个角分别是 $⟦0⟧^\circ$、$⟦1⟧^\circ$ 和 $⟦2⟧^\circ$。第四个角是多少度？`,
  '24pznbwnbef': R`四边形的内角和是 $360^\circ$：$360^\circ - ⟦0⟧^\circ - ⟦1⟧^\circ - ⟦2⟧^\circ = ⟦3⟧^\circ$。`,
