  'qinptcb6uu': R`正 ⟦0⟧ 边形（⟦1⟧）的每个内角是多少度？`,
  '1do1n0lapzc': R`内角和 $= (⟦0⟧ - 2) \times 180^\circ = ⟦1⟧^\circ$，平均分给 ⟦2⟧ 个相等的角：$⟦3⟧^\circ \div ⟦4⟧ = ⟦5⟧^\circ$。`,
  '2b3ubiiwfr4': R`在一个等腰三角形中，两腰的夹角（顶角）是 $⟦0⟧^\circ$。另外两个角各是多少度？`,
  '1m260esohws': R`两个底角相等：$\frac{180^\circ - ⟦0⟧^\circ}{2} = ⟦1⟧^\circ$。`,

