  '1b84zb92lm7': R`<p>成绩：12, 5, 9, 12, 7。</p><ul><li>平均数 $= \frac{12 + 5 + 9 + 12 + 7}{5} = \frac{45}{5} = 9$</li><li>排序：5, 7, 9, 12, 12 → 中位数 9</li><li>众数 12 · 极差 $12 - 5 = 7$</li></ul>`,
