  '26rnszv74s7': R`早上 6 点的气温是 $⟦0⟧^\circ\text{C}$。到中午气温上升了 $⟦1⟧^\circ\text{C}$，到午夜又比中午下降了 $⟦2⟧^\circ\text{C}$。午夜的气温是多少？`,
