  '2b2ar8gx2t7': R`<p>化简平方根时，把被开方数中最大的完全平方因数开出来：$\sqrt{ab} = \sqrt{a}\,\sqrt{b}$。</p>$$\sqrt{72} = \sqrt{36 \times 2} = 6\sqrt{2}$$`,
