  'pkpby3rsiu': R`将一枚均匀的骰子掷 ⟦0⟧ 次，预计掷出⟦1⟧的次数是多少？`,
  '1m2zbe7u1ww': R`$P = \frac{⟦0⟧}{6}$，所以期望次数为 $\frac{⟦1⟧}{6} \times ⟦2⟧ = ⟦3⟧$。`,
  '1eipzgu94sk': R`小于 3 的数`,
