  '2a86ul8z5e6': R`请输入分数，如 1/3。`,
  'wfhq8l2euu': R`有利结果：⟦0⟧——即 6 种中的 ⟦1⟧ 种。$P = \frac{⟦2⟧}{6}⟦3⟧$。`,
