<p><b>向量</b>既有大小又有方向。用坐标表示为 $\mathbf{a} = \begin{pmatrix} a_1 \\ a_2 \end{pmatrix}$ 或 $\begin{pmatrix} a_1 \\ a_2 \\ a_3 \end{pmatrix}$。从 $P$ 到 $Q$ 的向量是 $\overrightarrow{PQ} = \mathbf{q} - \mathbf{p}$。</p>
