  '1lyu4ddmyjw': R`与顺序有关：$^{⟦0⟧}P_{⟦1⟧} = ⟦2⟧ = ⟦3⟧$。`,
  'mt1d3k54sw': R`从 ⟦1⟧ 个人中选出 ⟦0⟧ 人组成委员会，有多少种选法？`,
  'jcb5dbxzw7': R`与顺序无关：$\binom{⟦0⟧}{⟦1⟧} = \frac{⟦2⟧!}{⟦3⟧!\,⟦4⟧!} = ⟦5⟧$。`,
  '1f3hbyul4kh': R`从 ⟦2⟧ 名男生和 ⟦3⟧ 名女生中选出 ⟦0⟧ 名男生和 ⟦1⟧ 名女生组成委员会。共有多少种不同的委员会？`,
  '219eq0t6hby': R`单词 <b>⟦0⟧</b> 的字母共有多少种不同的排列？`,
