  'qqcdrtkh5v': R`⟦0⟧ 个人围坐在一张圆桌旁（旋转后相同的算一种），有多少种坐法？`,
  '1n6howxe7gj': R`先固定一个人的座位以消除旋转，再排其余的人：$(⟦0⟧ - 1)! = ⟦1⟧$。`,
  '1hwymhgsxow': R`求 $(x + ⟦1⟧)^{⟦2⟧}$ 的展开式中 $x^{⟦0⟧}$ 的系数。`,
  '22kaf86ykzl': R`含 $x^{⟦0⟧}$ 的项是 $\binom{⟦1⟧}{⟦2⟧}x^{⟦3⟧}\cdot ⟦4⟧^{⟦5⟧}$，所以系数是 $⟦6⟧ \times ⟦7⟧ = ⟦8⟧$。`,
  '1zya3uq0ode': R`求 $(⟦1⟧x + 1)^{⟦2⟧}$ 的展开式中 $x^{⟦0⟧}$ 的系数。`,
  'po66a6fw7b': R`含 $x^{⟦0⟧}$ 的项是 $\binom{⟦1⟧}{⟦2⟧}(⟦3⟧x)^{⟦4⟧}$，所以系数是 $⟦5⟧ \times ⟦6⟧ = ⟦7⟧$。`,
  'yh0td3xino': R`你有 ⟦0⟧ 件衬衫、⟦1⟧ 条裤子和 ⟦2⟧ 双鞋。每样各选一件，能搭配出多少套不同的服装？`,
  'ruo6vpaqqc': R`分步乘法计数原理：$⟦0⟧ \times ⟦1⟧ \times ⟦2⟧ = ⟦3⟧$。`,
