  '1oou6k826kr': R`条件概率`,
  '1qgmh66fhna': R`<p>袋中有 5 个红球和 3 个蓝球，<b>不放回</b>地摸出两个。$P(\text{两个都是红球}) = \frac{5}{8} \times \frac{4}{7} = \frac{5}{14}$。如果有放回，则为 $\frac{5}{8} \times \frac{5}{8} = \frac{25}{64}$。</p>`,
  '6418q9b2s4': R`$$P(A \mid B) = \frac{P(B \mid A)\,P(A)}{P(B \mid A)P(A) + P(B \mid A')P(A')}$$<p>它把条件概率“反过来”——例如从 $P(\text{检测阳性} \mid \text{患病})$ 求出 $P(\text{患病} \mid \text{检测阳性})$。</p>`,
  '1zp2m1asa8t': R`<p>$P(A \mid B)$ 和 $P(B \mid A)$ 通常不相等。一项检测的准确率可以达到 99%，但当疾病很罕见时，阳性结果仍然更可能是误报。</p>`,
  '5fmcyqy5g8': R`袋中有 ⟦0⟧ 个红球和 ⟦1⟧ 个蓝球，不放回地摸出两个球。两个都是⟦2⟧球的概率是多少？`,
  '16uk5urbde9': R`$P(A) = ⟦0⟧$，$P(B) = ⟦1⟧$，$P(A \cap B) = ⟦2⟧$。求 $P(A \cup B)$。`,
  '2az4z9znymk': R`事件 $A$ 与 $B$ 相互独立，$P(A) = ⟦0⟧$，$P(B) = ⟦1⟧$。求 $P(A \cap B)$。`,
  '1ohoi8ye65': R`相互独立：$P(A \cap B) = ⟦0⟧ \times ⟦1⟧ = ⟦2⟧$。`,
  'ymjaeaaedm': R`事件 $A$ 与 $B$ 相互独立，$P(A) = ⟦0⟧$，$P(B) = ⟦1⟧$。求其中至少有一个发生的概率。`,
  'y6o9k7peax': R`$1 - P(\text{都不发生}) = 1 - (⟦0⟧)(⟦1⟧) = ⟦2⟧$。`,
  '2ct3qu61tjb': R`男生`,
