  '1mojcap1eui': R`一项调查的结果如下。⟦0⟧随机选出一人。已知此人属于“⟦1⟧”组，求此人属于“⟦2⟧”的概率。`,
  '1461hv2wfqt': R`只考虑“⟦1⟧”中的 ⟦0⟧ 人：$P = \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$。`,
  '12180tm9why': R`一项调查的结果如下。⟦0⟧随机选出一人。已知此人属于“⟦1⟧”，求此人属于“⟦2⟧”组的概率。`,
  'eppqyrg22a': R`将一枚均匀的骰子掷 ⟦0⟧ 次。至少出现一次 6 的概率是多少？`,
