  '1sg12en11ty': R`某种疾病的患病率为 ⟦0⟧%。一项检测能在 ⟦1⟧% 的患者身上检出该病，但对 ⟦2⟧% 的未患病者也会给出阳性结果。如果某人检测呈阳性，他患病的概率是多少？结果保留 3 位小数。`,
  '1n6kg7z10yy': R`袋中有 ⟦0⟧ 个红色筹码和 ⟦1⟧ 个蓝色筹码。摸出一个后放回，再摸出第二个。先红后蓝的概率是多少？`,
  '29cd8gay3w4': R`有放回时两次摸取相互独立：$\frac{⟦0⟧}{⟦1⟧} \times \frac{⟦2⟧}{⟦3⟧} = ⟦4⟧$。`,

