  'iohahpasm4': R`平均数 $= ⟦0⟧$；$\sigma^2 = \frac{⟦1⟧}{5} = ⟦2⟧$，所以 $\sigma = \sqrt{⟦3⟧} \approx ⟦4⟧$。`,
  'box0w6rodc': R`求下列数据的四分位距：⟦0⟧。（把数据分成两半时不含中位数。）`,
  'dvfyzp44sk': R`排序后：⟦0⟧。下半部分 ⟦1⟧ 得 $Q_1 = ⟦2⟧$；上半部分 ⟦3⟧ 得 $Q_3 = ⟦4⟧$。$\text{IQR} = ⟦5⟧ - ⟦6⟧ = ⟦7⟧$。`,
  '25jr4jzamls': R`一组数据的平均数为 ⟦0⟧，标准差为 ⟦1⟧。每个值都按 $y = ⟦2⟧x ⟦3⟧$ 变换。新的标准差是多少？`,
  '1h7x4xfpmhw': R`加上 ⟦0⟧ 不改变离散程度；乘以 ⟦1⟧ 使它变为原来的 $|⟦2⟧|$ 倍：$⟦3⟧ \times ⟦4⟧ = ⟦5⟧$。`,
  '158l5v4dkra': R`一组数据的平均数为 ⟦0⟧，标准差为 ⟦1⟧。每个值都按 $y = ⟦2⟧x ⟦3⟧$ 变换。新的平均数是多少？`,
  '21c6bmoi3b4': R`平均数按同样的方式变换：$⟦0⟧(⟦1⟧) ⟦2⟧ = ⟦3⟧$。`,
