  // conics
  '12p1gvv8rrs': R`
⟦0⟧
<h3>圆的方程</h3>
⟦1⟧
<p>展开后得到<b>一般式</b> $x^2 + y^2 + Dx + Ey + F = 0$，圆心为 $\left(-\frac{D}{2}, -\frac{E}{2}\right)$，半径为 $r = \sqrt{\frac{D^2}{4} + \frac{E^2}{4} - F}$。</p>
⟦2⟧
<h3>点与圆的位置关系</h3>
<p>把点代入 $(x - a)^2 + (y - b)^2$，与 $r^2$ 比较：较小 → 在圆内，相等 → 在圆上，较大 → 在圆外。</p>
<h3>切线</h3>
<p>切线垂直于过切点的半径。对于圆 $x^2 + y^2 = r^2$ 上的点 $(x_1, y_1)$，半径的斜率为 $\frac{y_1}{x_1}$，所以切线的斜率为 $-\frac{x_1}{y_1}$。</p>
<h3>抛物线</h3>
<p>$y^2 = 4px$ 的焦点为 $(p, 0)$，准线为 $x = -p$；$x^2 = 4py$ 的焦点为 $(0, p)$，准线为 $y = -p$。抛物线上每一点到焦点的距离都等于它到准线的距离。</p>
⟦3⟧`,
  'd8g3n0gso0': R`\text{中点 } \left(\frac{x_1 + x_2}{2}, \frac{y_1 + y_2}{2}\right) \qquad \text{距离 } \sqrt{(x_2 - x_1)^2 + (y_2 - y_1)^2}`,
  'yeziymovo4': R`$$(x - a)^2 + (y - b)^2 = r^2 \qquad \text{圆心 } (a, b), \text{ 半径 } r$$`,
  '16n3xjnynm7': R`<p>$x^2 + y^2 - 6x + 4y - 12 = 0$：配方得 $(x - 3)^2 + (y + 2)^2 = 12 + 9 + 4 = 25$。圆心 $(3, -2)$，半径 5。</p>`,
  '11ib4pk61jv': R`<p>在 $(x + 3)^2 + (y - 1)^2 = 16$ 中，圆心是 $(-3, 1)$——符号要反过来——半径是 4，不是 16。</p>`,
  'a19ymany96': R`求 $⟦0⟧$ 和 $⟦1⟧$ 的中点。`,
  'l7s72risy9': R`坐标分别取平均：$\left(\frac{⟦0⟧ + ⟦1⟧}{2}, \frac{⟦2⟧ + ⟦3⟧}{2}\right) = ⟦4⟧$。`,
  '1mu3r9x32jw': R`求圆 $⟦0⟧ = 0$ 的半径。`,
  '1bhxlcedykj': R`配方：$(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧ + ⟦3⟧ ⟦4⟧ = ⟦5⟧$，所以 $r = ⟦6⟧$。`,
  'd11etx15kp': R`求圆 $⟦0⟧ = 0$ 的圆心。`,
  '15nydo8wzsx': R`圆心为 $\left(-\frac{D}{2}, -\frac{E}{2}\right) = \left(-\frac{⟦0⟧}{2}, -\frac{⟦1⟧}{2}\right) = ⟦2⟧$。`,
  '10fdmgbsvjs': R`圆心为 $⟦0⟧$、半径为 ⟦1⟧ 的圆的方程是哪一个？`,
  'j31butbqt0': R`代入 $(x - a)^2 + (y - b)^2 = r^2$：$(x ⟦0⟧)^2 + (y ⟦1⟧)^2 = ⟦2⟧$。`,
  'qntj72wic0': R`在圆内`,
  '1z2fjcjol1w': R`圆内`,
  '1h4trl2qo1h': R`在圆上`,
  '1sg9ogxwlev': R`圆上`,
  '8uau8fsxbq': R`在圆外`,
  '6gv2pbcp7q': R`圆外`,
  '24luyo2ftju': R`点 $⟦0⟧$ 在圆 $(x ⟦1⟧)^2 + (y ⟦2⟧)^2 = ⟦3⟧$ 内、圆上还是圆外？`,
  '28keqi93flp': R`$⟦0⟧$，等于 $r^2 = ⟦1⟧$：该点在圆<b>上</b>。`,
  '1hj2pbrwkr7': R`$⟦0⟧$，小于 $r^2 = ⟦1⟧$：该点在圆<b>内</b>。`,
  'kv7senj1fr': R`$⟦0⟧$，大于 $r^2 = ⟦1⟧$：该点在圆<b>外</b>。`,
  '1hxz2qew8oz': R`求抛物线 $⟦0⟧$ 的焦点。`,
  '22fls2lezk5': R`与 ⟦0⟧ 比较：$4p = ⟦1⟧$，所以 $p = ⟦2⟧$，焦点为 $⟦3⟧$。`,
  'ez3m02hgj1': R`求 $x^2 + y^2 = ⟦0⟧$ 在点 $⟦1⟧$ 处切线的斜率。`,
  '1huwumypuyf': R`到 $⟦0⟧$ 的半径的斜率为 $\frac{⟦1⟧}{⟦2⟧}$。切线与之垂直：斜率 $= -\frac{⟦3⟧}{⟦4⟧} = ⟦5⟧$。`,

  // linear-programming
  '23l7ef2fdyh': R`
<p><b>线性规划</b>是在线性<b>约束条件</b>（如 $x + y \le 40$）下，求线性<b>目标函数</b>（如利润 $z = 30x + 20y$）的最优值（最大值或最小值）。</p>
<ol><li>把约束条件写成不等式（包括 $x \ge 0$，$y \ge 0$）。</li><li>画出每条边界线，并标出满足所有约束条件的区域——<b>可行域</b>。</li><li>两两联立边界方程，求出顶点（角点）。</li><li>在每个顶点处计算目标函数的值。</li></ol>
⟦0⟧
⟦1⟧
<p>对于约束为“≥”的最小化问题，可行域往往是无界的；当成本为正时，最小值仍然在某个顶点处取得。</p>
⟦2⟧`,
  'hs1573xprv': R`<p><b>顶点定理：</b>如果最优值存在，它一定在可行域的某个顶点处取得。</p>`,
  '1g8qhbmqb9w': R`<p>在 $x + y \le 8$，$2x + y \le 12$，$x, y \ge 0$ 的条件下，求 $z = 3x + 2y$ 的最大值。</p><p>顶点：$(0, 0)$，$(6, 0)$，$(4, 4)$［$x + y = 8$ 与 $2x + y = 12$ 的交点］，$(0, 8)$。</p><p>$z$ 的值：0, 18, 20, 16。最大值 $z = 20$，在 $(4, 4)$ 处取得。</p>`,
  '11p3z90h4pd': R`<p>检查每个顶点是否满足<b>所有</b>约束条件——两条边界线的交点可能在可行域之外。</p>`,
  '22hgo1z3v51': R`在 ⟦2⟧，$x \ge 0$，$y \ge 0$ 的条件下求 $z = ⟦0⟧ + ⟦1⟧$ 的最大值。$z$ 的最大值是多少？`,
  'thttp4dv20': R`各顶点及 $z$ 的值：⟦0⟧。最大值为 <b>⟦1⟧</b>。`,
  '2g9b1szo820': R`在 $x + y \ge ⟦2⟧$，$x + 2y \ge ⟦3⟧$，$x \ge 0$，$y \ge 0$ 的条件下求 $z = ⟦0⟧ + ⟦1⟧$ 的最小值。$z$ 的最小值是多少？`,
  '72m6dlh1yr': R`可行域无界，顶点为 ⟦0⟧。由于成本为正，最小值为 <b>⟦1⟧</b>。`,
  '4eos6o7rio': R`哪个点在由 ⟦0⟧，$x \ge 0$，$y \ge 0$ 确定的可行域内？`,
  '1jqzy1kt3ra': R`把每个点代入每个约束条件检验。$⟦0⟧$ 满足全部条件；其他各点都至少违反一个。`,
  '15d4uuzw5eq': R`一家面包店每天制作蛋糕（$x$ 个）和馅饼（$y$ 个）。每天最多能做 ⟦0⟧ 个，烘烤时间给出约束条件 ⟦1⟧。每个蛋糕利润 ⟦2⟧ 元，每个馅饼利润 ⟦3⟧ 元。每天的最大利润是多少？`,
  '296rrmt4h4q': R`约束条件：$x + y \le ⟦0⟧$，$⟦1⟧ \le ⟦2⟧$，$x, y \ge 0$。顶点：⟦3⟧。最大利润：<b>⟦4⟧</b> 元。`,

  // logic
  '22xng4phovn': R`
<p><b>命题</b>是可以判断真假的陈述句。用<b>逻辑联结词</b>可以构成复合命题：</p>
⟦0⟧
⟦1⟧
<h3>四种命题</h3>
⟦2⟧
<h3>量词</h3>
<p>$\forall$ 表示“所有”，$\exists$ 表示“存在”。否定时两者互换：“所有学生都及格了”的否定是“<b>有些</b>学生<b>没有</b>及格”；“有些鸟不会飞”的否定是“所有鸟都会飞”。</p>
<h3>有效推理</h3>
<ul><li><b>肯定前件式：</b>$p \Rightarrow q$，$p$；所以 $q$。</li><li><b>否定后件式：</b>$p \Rightarrow q$，$\neg q$；所以 $\neg p$。</li><li><b>三段论：</b>$p \Rightarrow q$，$q \Rightarrow r$；所以 $p \Rightarrow r$。</li></ul>
⟦3⟧`,
  '2aa32u1lmw9': R`真假`,
  '1h0id2d836q': R`<p>蕴含式 $p \Rightarrow q$ <b>只有</b>在 $p$ 真且 $q$ 假时才为假。</p>`,
  '2aojok6ubm7': R`形式`,
  '1bpxgxn3wdt': R`与原命题等价吗？`,
  'clyih3qga0': R`命题`,
