  '1vsuatfpf7o': R`否命题`,
  '1zjwynaslfy': R`逆否命题`,
  '2377erd9rpv': R`是`,
  '1vdptccpewy': R`<p>由 $p \Rightarrow q$ 和 $q$ <b>不能</b>推出 $p$（“肯定后件”谬误）。地面湿并不能证明下过雨。</p>`,
  'e62y0oj6y7': R`$p$ 为“⟦0⟧”，$q$ 为“⟦1⟧”，$r$ 为“⟦2⟧”。$⟦3⟧$ 的真值是什么？`,
  'x0xbdvafwl': R`代入 $p = \text{⟦0⟧}$，$q = \text{⟦1⟧}$，$r = \text{⟦2⟧}$，由内向外计算：$⟦3⟧$ 为<b>⟦4⟧</b>。（记住：$\Rightarrow$ 只有在 真 ⇒ 假 时为假。）`,
