  '14dtm0889wo': R`命题“⟦1⟧”的<b>⟦0⟧</b>是什么？`,
  '1izj6udg2zz': R`逆命题：交换条件和结论（$q \Rightarrow p$）。否命题：两者都否定（$\neg p \Rightarrow \neg q$）。逆否命题：交换并否定（$\neg q \Rightarrow \neg p$）。所以它的⟦0⟧是“⟦1⟧”⟦2⟧`,
